import{_ as i,o as a,c as t,ag as o}from"./chunks/framework.DXGyWiRo.js";const h=JSON.parse('{"title":"Remote Config File","description":"","frontmatter":{},"headers":[],"relativePath":"settings/remote-config.md","filePath":"settings/remote-config.md","lastUpdated":1786673734000}'),s={name:"settings/remote-config.md"};function n(l,e,r,c,p,d){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="remote-config-file" tabindex="-1">Remote Config File <a class="header-anchor" href="#remote-config-file" aria-label="Permalink to &quot;Remote Config File&quot;">​</a></h1><p>EasyYapi supports loading configuration files from remote URLs, making it easy to share configs across a team.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Remote config URLs are configured in the IDE settings, <strong>not</strong> in a config file key.</p><p>Open <strong>Settings → EasyApi → Rules → Remote</strong> sub-tab and add one URL per line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://your-config-server.com/easy-api.config</span></span></code></pre></div><ul><li>Each line is a remote URL that returns rule/config content.</li><li>Prefix a URL with <code>!</code> to disable it without removing it (e.g. <code>!http://config-server.com/legacy.config</code>).</li><li>Blank lines and whitespace are ignored.</li></ul><h2 id="including-remote-urls-from-a-config-file" tabindex="-1">Including Remote URLs from a Config File <a class="header-anchor" href="#including-remote-urls-from-a-config-file" aria-label="Permalink to &quot;Including Remote URLs from a Config File&quot;">​</a></h2><p>You can also pull a remote config from within a rule file using the <code>###include</code> directive:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###include https://raw.githubusercontent.com/org/repo/main/easyapi/common.rules</span></span></code></pre></div><p>See <a href="./local-file-config#including-other-config-files">Local Config File → Including Other Config Files</a> for full details on <code>###include</code> and the legacy <code>properties.additional</code> form.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>Remote config overrides extension and global rules, but project rules (<code>.easyapi/</code> / <code>.easy.api.config*</code> at the project root) take precedence over it</li><li>Supports multiple remote URLs (one per line in the Settings UI)</li><li>Supports auto-refresh</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Settings → EasyApi → Rules → Remote:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://config-server.com/common.easy.api.config</span></span>
<span class="line"><span>http://config-server.com/project-specific.easy.api.config</span></span></code></pre></div><p>Local config (lower priority than remote):</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">field.mock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=@mock</span></span></code></pre></div>`,18)])])}const u=i(s,[["render",n]]);export{h as __pageData,u as default};
